//! Modules generated by `cargo xtask codegen`; see `xtask/src/aarch64`.
//!
//! Generated code is tables written as `match`es (one arm per variant or
//! group of variants, so functions are long) and a decode tree of nested
//! `match`es and bit tests written uniformly as `word & mask == value`.
//! Switch arms list their values as or-patterns: measured about 15% faster
//! than ranges in the decode tree.
//! Bit tables are indexed by field values the generator sized them for, so
//! the indices are in bounds by construction. Operand code narrows field
//! values to operand types they fit by construction, keeps the parentheses
//! of its field extractions and imports the whole operand model. Encoding
//! and feature variants keep Arm's names. Alias conditions are AARCHMRS
//! expressions compiled literally (`BitCount(tsz) == 1` stays a bit count).

#![allow(
    clippy::match_same_arms,
    clippy::manual_range_patterns,
    clippy::too_many_lines,
    clippy::unreadable_literal,
    clippy::wildcard_enum_match_arm,
    clippy::upper_case_acronyms,
    clippy::verbose_bit_mask,
    clippy::if_not_else,
    clippy::collapsible_else_if,
    clippy::indexing_slicing,
    clippy::wildcard_imports,
    clippy::cast_possible_truncation,
    clippy::cast_possible_wrap,
    clippy::cast_sign_loss,
    clippy::cast_lossless,
    clippy::unnecessary_cast,
    clippy::unnested_or_patterns,
    clippy::double_parens,
    clippy::bool_to_int_with_if,
    clippy::collapsible_match,
    clippy::decimal_bitwise_operands,
    clippy::manual_is_power_of_two,
    clippy::comparison_chain,
    unused_parens,
    non_camel_case_types
)]

pub mod access;
pub mod decode;
pub mod encoding;
pub mod feature;
pub mod flow;
pub mod syntax;
pub mod sysreg;
